<script>
  function setUnit(unit) {
    const btnCm = document.getElementById('btn-cm');
    const btnIn = document.getElementById('btn-in');
    const chestCells = document.querySelectorAll('.val-chest');
    const waistCells = document.querySelectorAll('.val-waist');
    const hipsCells = document.querySelectorAll('.val-hips');

    if (unit === 'cm') {
      btnCm.className = 'px-3 py-1 rounded-full text-label-md font-label-md transition-all duration-200 bg-primary text-on-primary shadow-sm';
      btnIn.className = 'px-3 py-1 rounded-full text-label-md font-label-md transition-all duration-200 text-on-surface-variant';
      chestCells.forEach(el => el.textContent = el.getAttribute('data-cm'));
      waistCells.forEach(el => el.textContent = el.getAttribute('data-cm'));
      hipsCells.forEach(el => el.textContent = el.getAttribute('data-cm'));
    } else {
      btnIn.className = 'px-3 py-1 rounded-full text-label-md font-label-md transition-all duration-200 bg-primary text-on-primary shadow-sm';
      btnCm.className = 'px-3 py-1 rounded-full text-label-md font-label-md transition-all duration-200 text-on-surface-variant';
      chestCells.forEach(el => el.textContent = el.getAttribute('data-in'));
      waistCells.forEach(el => el.textContent = el.getAttribute('data-in'));
      hipsCells.forEach(el => el.textContent = el.getAttribute('data-in'));
    }
  }

  function highlightSizeRow(sizeKey) {
    const rows = ['S', 'M', 'L', 'XL'];
    rows.forEach(s => {
      const row = document.getElementById('row-' + s);
      if (s === sizeKey) {
        row.className = 'transition-colors duration-150 bg-secondary-container/30';
      } else {
        row.className = 'transition-colors duration-150';
      }
    });

    const pills = document.querySelectorAll('.size-pill');
    pills.forEach(pill => {
      if (pill.textContent.includes(sizeKey)) {
        pill.className = 'size-pill py-2 rounded-xl text-center font-label-md text-label-md bg-primary text-on-primary shadow-sm transition-all';
      } else {
        pill.className = 'size-pill py-2 rounded-xl text-center font-label-md text-label-md bg-surface-container text-on-surface hover:bg-surface-container-high transition-all';
      }
    });
  }

  function selectFitCut(btn, type) {
    const parent = btn.parentElement;
    parent.querySelectorAll('button').forEach(b => {
      b.className = 'px-2.5 py-1 rounded-lg text-label-md font-label-md bg-surface-container-lowest text-primary shadow-xs';
    });
    btn.className = 'px-2.5 py-1 rounded-lg text-label-md font-label-md bg-primary text-on-primary shadow-xs';
  }
